// meta's metabin: meta-analysis of binary outcomes (Mantel-Haenszel, Peto, inverse variance; OR, RR, RD). Written for
// rStats.js from the behaviour specification oracle/tsmeta-behaviour.md ("metabin") with the details found in
// experiments/tsmeta120-log.md (items 64-65, 97). No R or package source was read.

import { pchisq } from "../distributions/chisq.js";
import { pnorm, qnorm } from "../distributions/normal.js";
import { metaCore, type MetaCommonOptions, type MetaResult } from "./metagen.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const METABIN_KEYS = /* @__PURE__ */ new Set([
  "methodTau", "methodRandomCi", "sm", "method", "incr", "methodIncr", "allstudies", "MHexact", "QCochrane",
  "methodTauCi", "level", "levelMa", "levelPredict",
]);
// Generated by `node scripts/option-keys.mjs --write` (end)

/**
 * Options of {@link metabin}.
 *
 * @category Meta-analysis
 */
export interface MetabinOptions extends MetaCommonOptions {
  /** "RR" (default), "OR" or "RD". */
  sm?: "RR" | "OR" | "RD";
  /** "MH" (default), "Inverse" or "Peto" (OR only). */
  method?: "MH" | "Inverse" | "Peto";
  /** The continuity correction (default 0.5). */
  incr?: number;
  /** Which studies get it: "only0" (studies with a zero cell, default), "all", "if0all" (all when any has a zero). */
  methodIncr?: "only0" | "all" | "if0all";
  /** Keep studies with no or all events in both groups (default false; RD keeps them anyway). */
  allstudies?: boolean;
  /** The MH estimate without any increment (default false). */
  MHexact?: boolean;
  /** With methodTau "DL", Q about the MH estimate (default true). */
  QCochrane?: boolean;
}

const sum = (v: readonly number[]): number => v.reduce((a, b) => a + b, 0);

/**
 * Meta-analysis of binary outcomes (meta's `metabin()`): events e1 / e2 of totals n1 / n2. The common effect by
 * Mantel-Haenszel (OR with the Robins-Breslow-Greenland variance; RR and RD with Greenland and Robins'), Peto's
 * (O - E) / V or the inverse variance; the random effect and heterogeneity as {@link metagen} on the study values.
 * Studies with a zero cell get `incr` (0.5); studies with no or all events in both groups are left out for OR and RR.
 * Equivalent to `meta::metabin()` in R.
 *
 * @category Meta-analysis
 */
export function metabin(e1: readonly number[], n1: readonly number[], e2: readonly number[], n2: readonly number[], options: MetabinOptions = {}): MetaResult {
  checkOptions(options, METABIN_KEYS, "metabin"); // generated: option-keys.mjs
  const K = e1.length;
  if (![n1, e2, n2].every((v) => v.length === K)) throw new RangeError("metabin: e1, n1, e2 and n2 must have the same length");
  for (let i = 0; i < K; i++) if (!(e1[i]! >= 0 && e1[i]! <= n1[i]! && e2[i]! >= 0 && e2[i]! <= n2[i]! && n1[i]! > 0 && n2[i]! > 0)) throw new RangeError("metabin: events must lie in 0..n and n > 0");
  const sm = options.sm ?? "RR"; const method = options.method ?? "MH"; const incr = options.incr ?? 0.5; const mi = options.methodIncr ?? "only0";
  if (method === "Peto" && sm !== "OR") throw new RangeError("metabin: Peto's method is for sm = 'OR'");
  const a = e1.map(Number), c = e2.map(Number), b = a.map((x, i) => n1[i]! - x), d = c.map((x, i) => n2[i]! - x);
  const zeroCell = a.map((_, i) => a[i] === 0 || b[i] === 0 || c[i] === 0 || d[i] === 0);
  const doubleZero = a.map((_, i) => (a[i] === 0 && c[i] === 0) || (b[i] === 0 && d[i] === 0));
  const keep = a.map((_, i) => sm === "RD" || options.allstudies || !doubleZero[i]);
  const anyZero = zeroCell.some((z, i) => z && keep[i]);
  const inc = a.map((_, i) => (mi === "all" || (mi === "if0all" && anyZero) || zeroCell[i] ? incr : 0));
  // study values
  const TE = new Array<number>(K).fill(NaN), seTE = new Array<number>(K).fill(NaN);
  for (let i = 0; i < K; i++) {
    if (!keep[i]) continue;
    const t = inc[i]!; const A = a[i]! + t, B = b[i]! + t, C = c[i]! + t, D = d[i]! + t;
    if (method === "Peto") {
      const N = n1[i]! + n2[i]!; const m1 = a[i]! + c[i]!;
      const E = (n1[i]! * m1) / N; const V = (n1[i]! * n2[i]! * m1 * (N - m1)) / (N * N * (N - 1));
      TE[i] = (a[i]! - E) / V; seTE[i] = 1 / Math.sqrt(V);
    } else if (sm === "OR") { TE[i] = Math.log((A * D) / (B * C)); seTE[i] = Math.sqrt(1 / A + 1 / B + 1 / C + 1 / D); }
    else if (sm === "RR") {
      const N1 = n1[i]! + t, N2 = n2[i]! + t; // the increment added once to the group size (log 65)
      TE[i] = Math.log(A / N1) - Math.log(C / N2); seTE[i] = Math.sqrt(1 / A - 1 / N1 + 1 / C - 1 / N2);
    } else {
      TE[i] = a[i]! / n1[i]! - c[i]! / n2[i]!; // the raw difference, the variance of the incremented cells
      seTE[i] = Math.sqrt((A * B) / (A + B) ** 3 + (C * D) / (C + D) ** 3);
    }
  }
  const idx = TE.map((v, i) => (keep[i] && Number.isFinite(v) && Number.isFinite(seTE[i]!) && seTE[i]! > 0 ? i : -1)).filter((i) => i >= 0);
  const core = metaCore(idx.map((i) => TE[i]!), idx.map((i) => seTE[i]!), options);
  const res: MetaResult = { ...core, TE, seTE, k: idx.length };
  const spread = (v: readonly number[]): number[] => { const o = new Array<number>(K).fill(0); idx.forEach((i, j) => { o[i] = v[j]!; }); return o; };
  res["w.random"] = spread(core["w.random"]);
  const level = options.levelMa ?? options.level ?? 0.95; const z = qnorm(0.5 + level / 2) as number;
  const setCommon = (te: number, se: number, w: number[]): void => {
    const st = te / se;
    Object.assign(res, { "TE.common": te, "seTE.common": se, "lower.common": te - z * se, "upper.common": te + z * se, "statistic.common": st, "pval.common": 2 * (pnorm(-Math.abs(st)) as number), "w.common": w });
  };
  if (method === "Peto") {
    // Peto: sum(O - E) / sum(V), the inverse variance of the study values
    setCommon(core["TE.common"], core["seTE.common"], spread(core["w.common"]));
  } else if (method === "MH") {
    // MH.exact drops the increment
    const t = a.map((_, i) => (options.MHexact ? 0 : inc[i]!));
    const A = idx.map((i) => a[i]! + t[i]!), B = idx.map((i) => b[i]! + t[i]!), C = idx.map((i) => c[i]! + t[i]!), D = idx.map((i) => d[i]! + t[i]!);
    const N1 = A.map((x, j) => x + B[j]!), N2 = C.map((x, j) => x + D[j]!), N = N1.map((x, j) => x + N2[j]!);
    let te: number, se: number, w: number[];
    if (sm === "OR") {
      const R = A.map((x, j) => (x * D[j]!) / N[j]!), S = B.map((x, j) => (x * C[j]!) / N[j]!);
      const P = A.map((x, j) => (x + D[j]!) / N[j]!), Qv = B.map((x, j) => (x + C[j]!) / N[j]!);
      const sR = sum(R), sS = sum(S);
      te = Math.log(sR / sS);
      se = Math.sqrt(sum(P.map((p, j) => p * R[j]!)) / (2 * sR * sR) + sum(P.map((p, j) => p * S[j]! + Qv[j]! * R[j]!)) / (2 * sR * sS) + sum(Qv.map((q, j) => q * S[j]!)) / (2 * sS * sS));
      w = S;
    } else if (sm === "RR") {
      const R = A.map((x, j) => (x * N2[j]!) / N[j]!), S = C.map((x, j) => (x * N1[j]!) / N[j]!);
      te = Math.log(sum(R) / sum(S));
      se = Math.sqrt(sum(N.map((n, j) => (N1[j]! * N2[j]! * (A[j]! + C[j]!) - A[j]! * C[j]! * n) / (n * n))) / (sum(R) * sum(S)));
      w = S;
    } else {
      // the weights from the incremented group sizes, the raw risk differences (log 97)
      const W = N1.map((x, j) => (x * N2[j]!) / N[j]!);
      te = sum(W.map((wj, j) => wj * TE[idx[j]!]!)) / sum(W);
      se = Math.sqrt(sum(N.map((n, j) => (A[j]! * B[j]! * N2[j]! ** 3 + C[j]! * D[j]! * N1[j]! ** 3) / (N1[j]! * N2[j]! * n * n))) / sum(W) ** 2);
      w = W;
    }
    setCommon(te, se, spread(w));
    // with DL and Q.Cochrane, Q (and so DL's tau2) is taken about the MH estimate
    if ((options.methodTau ?? "REML") === "DL" && (options.QCochrane ?? true)) {
      const ti = idx.map((i) => TE[i]!), wi = idx.map((i) => 1 / seTE[i]! ** 2);
      const Q = sum(ti.map((x, j) => wi[j]! * (x - te) ** 2)); const df = idx.length - 1;
      const sw = sum(wi); const tau2 = Math.max(0, (Q - df) / (sw - sum(wi.map((x) => x * x)) / sw));
      const re = metaCore(ti, idx.map((i) => seTE[i]!), { ...options, methodTau: "DL", fixedTau2: tau2, fixedQ: Q });
      Object.assign(res, pickRandom(re), { Q, "pval.Q": pchisq(Q, df, { lowerTail: false }) as number, "w.random": spread(re["w.random"]) });
    }
  } else setCommon(core["TE.common"], core["seTE.common"], spread(core["w.common"]));
  return res;
}

function pickRandom(m: MetaResult): Partial<MetaResult> {
  const keys = ["TE.random", "seTE.random", "lower.random", "upper.random", "statistic.random", "pval.random", "df.random", "seTE.predict", "lower.predict", "upper.predict",
    "tau2", "lower.tau2", "upper.tau2", "tau", "lower.tau", "upper.tau", "H", "lower.H", "upper.H", "I2", "lower.I2", "upper.I2"] as const;
  const o: Record<string, unknown> = {}; for (const k of keys) o[k] = m[k];
  return o as Partial<MetaResult>;
}
